-- Chak De DoMS 2026 Auction — Supabase setup
-- Run this entire file in Supabase SQL Editor.

create extension if not exists pgcrypto;

create table if not exists public.players (
  id bigint generated by default as identity primary key,
  name text not null,
  roll text,
  gender text,
  skill text,
  experience integer check (experience between 1 and 5),
  program text,
  photo text,
  photo_id text,
  created_at timestamptz not null default now()
);

create table if not exists public.teams (
  id bigint generated by default as identity primary key,
  name text not null,
  start_purse integer not null default 1000 check (start_purse >= 0),
  purse integer not null default 1000 check (purse >= 0),
  spent integer not null default 0 check (spent >= 0),
  created_at timestamptz not null default now()
);

create table if not exists public.auction_state (
  id integer primary key default 1 check (id=1),
  current_player_id bigint references public.players(id),
  stage text not null default 'ready' check (stage in ('ready','on_auction','sold','unsold')),
  winning_team_id bigint references public.teams(id),
  sale_price integer,
  updated_at timestamptz not null default now()
);

create table if not exists public.auction_sales (
  id bigint generated by default as identity primary key,
  player_id bigint not null references public.players(id),
  team_id bigint references public.teams(id),
  price integer not null default 0 check (price >= 0),
  status text not null check (status in ('sold','unsold')),
  created_at timestamptz not null default now()
);

create unique index if not exists auction_sales_player_once on public.auction_sales(player_id);
create unique index if not exists auction_state_one on public.auction_state(id);

insert into public.auction_state(id) values (1) on conflict (id) do nothing;

