 name text, roll text, gender text, skill text, experience integer,
 program text, photo text, photo_id text
)
where not exists (select 1 from public.players p where p.roll=x.roll and x.roll is not null and x.roll <> '');

-- Basic RLS: public can read players/teams/state/sales; only authenticated admin can mutate.
alter table public.players enable row level security;
alter table public.teams enable row level security;
alter table public.auction_state enable row level security;
alter table public.auction_sales enable row level security;

drop policy if exists "public read players" on public.players;
create policy "public read players" on public.players for select to anon, authenticated using (true);

drop policy if exists "public read teams" on public.teams;
create policy "public read teams" on public.teams for select to anon, authenticated using (true);

drop policy if exists "public read state" on public.auction_state;
create policy "public read state" on public.auction_state for select to anon, authenticated using (true);

drop policy if exists "public read sales" on public.auction_sales;
create policy "public read sales" on public.auction_sales for select to anon, authenticated using (true);

drop policy if exists "admin manage players" on public.players;
create policy "admin manage players" on public.players for all to authenticated using (true) with check (true);

drop policy if exists "admin manage teams" on public.teams;
create policy "admin manage teams" on public.teams for all to authenticated using (true) with check (true);

drop policy if exists "admin manage state" on public.auction_state;
create policy "admin manage state" on public.auction_state for all to authenticated using (true) with check (true);

drop policy if exists "admin manage sales" on public.auction_sales;
create policy "admin manage sales" on public.auction_sales for all to authenticated using (true) with check (true);

-- Realtime publication for live display updates.
do $$
begin
  alter publication supabase_realtime add table public.auction_state;
exception when duplicate_object then null;
end $$;

do $$
begin
  alter publication supabase_realtime add table public.teams;
exception when duplicate_object then null;
end $$;

do $$
begin
  alter publication supabase_realtime add table public.auction_sales;
exception when duplicate_object then null;
end $$;

-- Default teams (edit in Admin UI later).
insert into public.teams(name,start_purse,purse,spent)
select v.name,1000,1000,0 from (values ('Team A'),('Team B'),('Team C'),('Team D')) v(name)
where not exists (select 1 from public.teams);
